import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/faq/index.md","filePath":"zh/faq/index.md","lastUpdated":1790683574000}'),l={name:"zh/faq/index.md"};function i(n,a,s,h,p,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>本页收录的都是<strong>真实出现过</strong>的问题。</p><h2 id="配置类" tabindex="-1">配置类 <a class="header-anchor" href="#配置类" aria-label="Permalink to &quot;配置类&quot;">​</a></h2><h3 id="后台改了配置-用户端没变化" tabindex="-1">后台改了配置，用户端没变化？ <a class="header-anchor" href="#后台改了配置-用户端没变化" aria-label="Permalink to &quot;后台改了配置，用户端没变化？&quot;">​</a></h3><p>用户端的配置是<strong>启动时拉取一次</strong>的。运营改完之后：</p><ul><li><strong>App</strong>：用户需要<strong>完全退出 App 再重新打开</strong>（切到后台不算），下次启动才会拿到新配置</li><li><strong>网页端（PC / H5）</strong>：刷新页面即可</li></ul><h3 id="配置明明填了-用户端却显示-暂无数据" tabindex="-1">配置明明填了，用户端却显示&quot;暂无数据&quot;？ <a class="header-anchor" href="#配置明明填了-用户端却显示-暂无数据" aria-label="Permalink to &quot;配置明明填了，用户端却显示&quot;暂无数据&quot;？&quot;">​</a></h3><p>先检查该项的<strong>开关是否打开</strong>。列表类配置（底部栏、金刚区、侧边栏、下载地址等）中，未开启的条目不会下发到用户端；如果整组都没开，用户端就是空的。</p><h3 id="下载中心的链接点了没反应" tabindex="-1">下载中心的链接点了没反应？ <a class="header-anchor" href="#下载中心的链接点了没反应" aria-label="Permalink to &quot;下载中心的链接点了没反应？&quot;">​</a></h3><p>检查下载地址是否<strong>带了 <code>http://</code> 或 <code>https://</code> 前缀</strong>。只填域名（如 <code>example.com</code>）在部分端上会被当成站内相对路径，导致点击无效。</p><h3 id="白皮书打不开-显示空白" tabindex="-1">白皮书打不开 / 显示空白？ <a class="header-anchor" href="#白皮书打不开-显示空白" aria-label="Permalink to &quot;白皮书打不开 / 显示空白？&quot;">​</a></h3><p>白皮书建议配置<strong>网页地址或 PDF</strong>。如果配的是 <code>.doc</code> 文件，用户端的内嵌浏览器无法渲染，表现就是一片空白。</p><h2 id="app-类" tabindex="-1">App 类 <a class="header-anchor" href="#app-类" aria-label="Permalink to &quot;App 类&quot;">​</a></h2><h3 id="用户装不上-app-提示-应用未安装" tabindex="-1">用户装不上 App，提示&quot;应用未安装&quot;？ <a class="header-anchor" href="#用户装不上-app-提示-应用未安装" aria-label="Permalink to &quot;用户装不上 App，提示&quot;应用未安装&quot;？&quot;">​</a></h3><p>多半是手机上装过<strong>来源不同的同名 App</strong>（比如从其他渠道下载的旧包）。签名不一致无法覆盖安装，需要先卸载旧版本。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>卸载会清空本地数据，用户需要重新登录。</p></div><h3 id="用户收不到更新提示" tabindex="-1">用户收不到更新提示？ <a class="header-anchor" href="#用户收不到更新提示" aria-label="Permalink to &quot;用户收不到更新提示？&quot;">​</a></h3><p>按顺序检查：</p><ol><li>「基础配置 → App版本更新」的<strong>总开关</strong>是否打开</li><li>「最新版本号」是否<strong>大于</strong>用户当前安装的版本号</li><li>用户是否当天已经点过「稍后再说」——点过之后当天不再提示</li><li>用户是否<strong>完全退出并重新打开</strong>了 App</li></ol><h3 id="用户点了更新-下载失败" tabindex="-1">用户点了更新，下载失败？ <a class="header-anchor" href="#用户点了更新-下载失败" aria-label="Permalink to &quot;用户点了更新，下载失败？&quot;">​</a></h3><p>先自己在浏览器里打开配置的下载地址，确认能正常下载。如果链接本身就打不开，说明安装包还没上传或地址填错了。</p><h2 id="资金类" tabindex="-1">资金类 <a class="header-anchor" href="#资金类" aria-label="Permalink to &quot;资金类&quot;">​</a></h2><h3 id="用户说充值没到账" tabindex="-1">用户说充值没到账？ <a class="header-anchor" href="#用户说充值没到账" aria-label="Permalink to &quot;用户说充值没到账？&quot;">​</a></h3><ol><li>先确认用户<strong>转账的链（网络）与所选币种是否匹配</strong>。充错链的资产通常无法找回</li><li>在后台「充值记录」中按 UID 查询是否有对应记录</li><li>链上确认需要时间，不同链的确认速度差异较大</li></ol><h3 id="用户说余额对不上" tabindex="-1">用户说余额对不上？ <a class="header-anchor" href="#用户说余额对不上" aria-label="Permalink to &quot;用户说余额对不上？&quot;">​</a></h3><p>拉该用户的<strong>完整资金流水</strong>逐条核对。每条流水都记录了变动金额与变动前后的余额，能够定位到具体是哪一笔出的偏差。</p><div class="danger custom-block"><p class="custom-block-title">不要用调账&quot;抹平&quot;</p><p>发现对不上时，先查清原因再处理。直接用后台调账把余额改成&quot;看起来对&quot;的数字，会让后续核账更困难。</p></div><h3 id="提现审核通过后能撤回吗" tabindex="-1">提现审核通过后能撤回吗？ <a class="header-anchor" href="#提现审核通过后能撤回吗" aria-label="Permalink to &quot;提现审核通过后能撤回吗？&quot;">​</a></h3><p><strong>不能。</strong> 审核通过会发起真实的链上转账，一经发出无法撤回。审核时请务必核对地址、网络与金额。</p><h2 id="客服类" tabindex="-1">客服类 <a class="header-anchor" href="#客服类" aria-label="Permalink to &quot;客服类&quot;">​</a></h2><h3 id="用户在-app-发了消息-客服群里没动静" tabindex="-1">用户在 App 发了消息，客服群里没动静？ <a class="header-anchor" href="#用户在-app-发了消息-客服群里没动静" aria-label="Permalink to &quot;用户在 App 发了消息，客服群里没动静？&quot;">​</a></h3><p>多半是群配错了：「客服群组 ID」必须填<strong>开启了话题的超级群</strong>，不能是私聊；机器人要是群管理员，且<strong>单独勾选「管理话题」权限</strong>。完整排查顺序见<a href="/CoinExchange/zh/guide/customer-service#常见问题">在线客服</a>。</p><h3 id="客服在-telegram-回了-用户-app-里收不到" tabindex="-1">客服在 Telegram 回了，用户 App 里收不到？ <a class="header-anchor" href="#客服在-telegram-回了-用户-app-里收不到" aria-label="Permalink to &quot;客服在 Telegram 回了，用户 App 里收不到？&quot;">​</a></h3><p>消息进得去、回不来，问题在回调：后台「第三方配置 → 在线客服」里的<strong>回调地址与回调密钥</strong>是否都填了、填完是否重新保存过。缺任何一项，界面仍显示保存成功，但回调不会登记。</p><h3 id="客服回了语音-用户说没收到" tabindex="-1">客服回了语音，用户说没收到？ <a class="header-anchor" href="#客服回了语音-用户说没收到" aria-label="Permalink to &quot;客服回了语音，用户说没收到？&quot;">​</a></h3><p>目前只转发<strong>文字、表情和图片</strong>，语音与文件不会送到 App。</p><h2 id="用户端体验类" tabindex="-1">用户端体验类 <a class="header-anchor" href="#用户端体验类" aria-label="Permalink to &quot;用户端体验类&quot;">​</a></h2><h3 id="用户反馈倒计时和实际结算时间对不上" tabindex="-1">用户反馈倒计时和实际结算时间对不上？ <a class="header-anchor" href="#用户反馈倒计时和实际结算时间对不上" aria-label="Permalink to &quot;用户反馈倒计时和实际结算时间对不上？&quot;">​</a></h3><p>秒合约的倒计时以<strong>服务端定盘时刻</strong>为唯一基准，客户端会做授时校准。如果用户手机系统时间偏差很大，视觉上可能有短暂差异，但实际结算以服务端为准。</p><h3 id="用户端语言不全-某些文字还是中文" tabindex="-1">用户端语言不全 / 某些文字还是中文？ <a class="header-anchor" href="#用户端语言不全-某些文字还是中文" aria-label="Permalink to &quot;用户端语言不全 / 某些文字还是中文？&quot;">​</a></h3><p>用户端支持 7 种语言，语言列表由后台的语言字典控制。如果发现某个新功能的文案未翻译，请反馈给技术方补充语言包。</p><hr><div class="tip custom-block"><p class="custom-block-title">没找到答案</p><p>如果问题涉及资金差异、订单异常或系统报错，请提供：<strong>用户 UID、发生时间、涉及金额、App 版本号</strong>（在「我的」页面最下方），并联系技术支持。</p></div>',43)])])}const q=t(l,[["render",i]]);export{u as __pageData,q as default};
